mapper.select:
select s.id, s.student_no, s.name, s.gender, s.status, coalesce(round(avg(g.score), 1), 0) growth_index from student s left join growth_record g on g.student_id = s.id where s.status = 'ACTIVE'
and (s.name like #{like} or s.student_no like #{like})
group by s.id, s.student_no, s.name, s.gender, s.status order by s.id limit #{size} offset #{offset}
